// 백엔드가 보낸 문단들을 Anthropic Messages API 요청 본문으로 만듭니다.
// 문단을 하나씩 보내지 않고 한 번에 넘기는 이유: 앞뒤 문맥이 있어야 용어가
// 일관되게 번역되고, 요청 수도 줄어듭니다.
const body = $json.body ?? $json;
const texts = body.texts ?? [];
const source = body.source && body.source !== 'auto' ? body.source : '원문';
const target = body.target || 'ko';

if (!Array.isArray(texts) || texts.length === 0) {
  throw new Error('texts가 비어 있습니다');
}

const system = [
  '당신은 학술 논문 번역가입니다. 주어진 문단들을 ' + target + '로 번역하세요.',
  '',
  '규칙:',
  '- 입력 문단 하나당 번역문 하나. 개수와 순서를 절대 바꾸지 마세요.',
  '- 문단을 합치거나 나누지 마세요. 요약하지 말고 전부 번역하세요.',
  '- 전문용어는 문서 전체에서 같은 번역어를 쓰세요. 처음 나올 때만 원어를 괄호로 병기합니다.',
  '- 수식, 변수명, 인용 표시([12] 등), 그림·표 번호는 원문 그대로 두세요.',
  '- 제목이나 절 제목처럼 짧은 문단도 그대로 번역해 같은 자리에 두세요.',
  '- 번역할 내용이 없는 문단(숫자·기호뿐)은 원문을 그대로 돌려주세요.',
  '- 설명이나 주석을 덧붙이지 말고 번역문만 담으세요.',
  '- 응답에 내부용 XML 태그를 포함하지 마세요.',
].join('\n');

const userText = texts
  .map((t, i) => '[' + i + '] ' + t)
  .join('\n\n');

return [{
  json: {
    model: 'claude-opus-5',
    max_tokens: 16000,
    // 번역은 추론이 필요한 작업이 아니라 지연과 비용만 늘립니다. Opus 5는 thinking이
    // 기본 on이라 명시적으로 끕니다(effort high 이하에서만 허용).
    thinking: { type: 'disabled' },
    system,
    output_config: {
      effort: 'low',
      // 구조화 출력 — 모델이 스키마를 벗어난 응답을 내놓을 수 없게 합니다.
      // 프롬프트로 "JSON만 답하라"고 부탁하고 파싱 실패를 재시도하는 것보다 확실합니다.
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: {
            translations: {
              type: 'array',
              description: '입력 문단과 같은 개수·순서의 번역문',
              items: { type: 'string' },
            },
          },
          required: ['translations'],
          additionalProperties: false,
        },
      },
    },
    messages: [{
      role: 'user',
      content: '다음 ' + texts.length + '개 문단(' + source + ')을 번역하세요. 번호는 순서 확인용이니 번역문에는 넣지 마세요.\n\n' + userText,
    }],
  },
}];

// 구조화 출력이라 content[0].text는 스키마를 지킨 JSON 문자열입니다.
// 그래도 모델이 거부(refusal)했거나 max_tokens에 걸렸을 수 있어 확인합니다.
const res = $json;

if (res.stop_reason === 'refusal') {
  throw new Error('모델이 번역을 거부했습니다 (' + (res.stop_details?.category ?? 'unknown') + ')');
}

const block = (res.content ?? []).find((b) => b.type === 'text');
if (!block) {
  throw new Error('응답에 텍스트가 없습니다 (stop_reason=' + res.stop_reason + ')');
}

let parsed;
try {
  parsed = JSON.parse(block.text);
} catch (e) {
  // max_tokens에 걸려 JSON이 잘리면 여기로 옵니다 — 문단 수를 줄여야 한다는 신호.
  throw new Error('번역 결과를 읽지 못했습니다 (stop_reason=' + res.stop_reason + ')');
}

const translations = parsed.translations;
if (!Array.isArray(translations)) {
  throw new Error('translations 배열이 없습니다');
}

return [{ json: { translations } }];
